  assert.equal(r.value.discount, 500000);
  // VAT: (10000000 - 500000) * 0.21 = 1995000
  assert.equal(r.value.vat, 1995000);
});

// Bulk discount tests (2.5% extra discount on qty >= 10, applied after base discount)
test('invoiceTotals with qty < 10 has no bulk discount', () => {
  const invoice = {
    lines: [{ qty: 9, unitPrice: 1000, discountPercent: 0, vatRate: 0 }],
  };
  const r = invoiceTotals(invoice);
  assert.equal(r.ok, true);
  assert.equal(r.value.subtotal, 9000);
  assert.equal(r.value.discount, 0);
  assert.equal(r.value.total, 9000);
});

test('invoiceTotals with qty = 10 applies bulk discount', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 1000, discountPercent: 0, vatRate: 0 }],
  };
  const r = invoiceTotals(invoice);
  assert.equal(r.ok, true);
  assert.equal(r.value.subtotal, 10000);
  // Bulk discount: 10000 * 0.025 = 250
  assert.equal(r.value.discount, 250);
  assert.equal(r.value.total, 9750);
});

test('invoiceTotals with qty > 10 applies bulk discount', () => {
  const invoice = {
    lines: [{ qty: 15, unitPrice: 1000, discountPercent: 0, vatRate: 0 }],
  };
  const r = invoiceTotals(invoice);
  assert.equal(r.ok, true);
  assert.equal(r.value.subtotal, 15000);
  // Bulk discount: 15000 * 0.025 = 375
  assert.equal(r.value.discount, 375);
  assert.equal(r.value.total, 14625);
});

test('invoiceTotals bulk discount applied after base discount', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 1000, discountPercent: 10, vatRate: 0 }],
  };
  const r = invoiceTotals(invoice);
  assert.equal(r.ok, true);
  assert.equal(r.value.subtotal, 10000);
  // Base discount: 10000 * 0.10 = 1000
  // Remaining: 10000 - 1000 = 9000
  // Bulk discount: 9000 * 0.025 = 225
  // Total discount: 1000 + 225 = 1225
  assert.equal(r.value.discount, 1225);
  assert.equal(r.value.total, 8775);
});

test('invoiceTotals bulk discount with VAT', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 1000, discountPercent: 0, vatRate: 21 }],
  };
  const r = invoiceTotals(invoice);
  assert.equal(r.ok, true);
  assert.equal(r.value.subtotal, 10000);
  // Bulk discount: 10000 * 0.025 = 250
  assert.equal(r.value.discount, 250);
  // VAT on (10000 - 250) = 9750 * 0.21 = 2047.5 -> 2048 (banker's rounding)
  assert.equal(r.value.vat, 2048);
  assert.equal(r.value.total, 11798);
});

test('invoiceTotals bulk discount with both base discount and VAT', () => {
  const invoice = {
    lines: [{ qty: 20, unitPrice: 8500, discountPercent: 5, vatRate: 21 }],
  };
  const r = invoiceTotals(invoice);
  assert.equal(r.ok, true);
  assert.equal(r.value.subtotal, 170000);
  // Base discount: 170000 * 0.05 = 8500
  // Remaining: 170000 - 8500 = 161500
  // Bulk discount: 161500 * 0.025 = 4037.5 -> 4038 (banker's rounding)
  // Total discount: 8500 + 4038 = 12538
  assert.equal(r.value.discount, 12538);
  // VAT on (170000 - 12538) = 157462 * 0.21 = 33067.02 -> 33067
  assert.equal(r.value.vat, 33067);
});

test('invoiceTotals multiple lines with bulk discount on some', () => {
  const invoice = {
    lines: [
      { qty: 5, unitPrice: 1000, discountPercent: 0, vatRate: 0 }, // No bulk discount
      { qty: 10, unitPrice: 1000, discountPercent: 0, vatRate: 0 }, // Bulk discount
    ],
  };
  const r = invoiceTotals(invoice);
  assert.equal(r.ok, true);
  assert.equal(r.value.subtotal, 15000);
  // Line 1: 5000 * 0 = 0
  // Line 2: 10000 * 0.025 = 250
  assert.equal(r.value.discount, 250);
  assert.equal(r.value.total, 14750);
});

test('invoiceTotals bulk discount with 100% base discount', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 1000, discountPercent: 100, vatRate: 0 }],
  };
  const r = invoiceTotals(invoice);
  assert.equal(r.ok, true);
  assert.equal(r.value.subtotal, 10000);
  // Base discount: 10000 * 1 = 10000
  // Remaining: 0
  // Bulk discount: 0 * 0.025 = 0
  // Total discount: 10000
  assert.equal(r.value.discount, 10000);
  assert.equal(r.value.total, 0);
});

test('invoiceTotals bulk discount rounding precision', () => {
  const invoice = {
    lines: [{ qty: 11, unitPrice: 333, discountPercent: 0, vatRate: 0 }],
  };
  const r = invoiceTotals(invoice);
  assert.equal(r.ok, true);
  assert.equal(r.value.subtotal, 3663);
  // Bulk discount: 3663 * 0.025 = 91.575 -> 92 (banker's rounding)
  assert.equal(r.value.discount, 92);
  assert.equal(r.value.total, 3571);
});

test('invoiceTotals bulk discount with large qty', () => {
  const invoice = {
    lines: [{ qty: 100, unitPrice: 100, discountPercent: 0, vatRate: 0 }],
  };
  const r = invoiceTotals(invoice);
  assert.equal(r.ok, true);
  assert.equal(r.value.subtotal, 10000);
  // Bulk discount: 10000 * 0.025 = 250
  assert.equal(r.value.discount, 250);
  assert.equal(r.value.total, 9750);
});

test('invoiceTotals bulk discount boundary: qty = 9 vs qty = 10', () => {
  const inv9 = {
    lines: [{ qty: 9, unitPrice: 1000, discountPercent: 0, vatRate: 0 }],
  };
  const r9 = invoiceTotals(inv9);

  const inv10 = {
    lines: [{ qty: 10, unitPrice: 1000, discountPercent: 0, vatRate: 0 }],
  };
  const r10 = invoiceTotals(inv10);

  // qty = 9: 9000 total
  assert.equal(r9.value.total, 9000);
  // qty = 10: 9750 total (250 bulk discount)
  assert.equal(r10.value.total, 9750);
  // Difference is exactly 250 (the bulk discount)
  assert.equal(r9.value.total - r10.value.total, 250);
});

test('invoiceTotals bulk discount with tier discount', () => {
  // Simulating a customer with tier discount that would be set in createInvoice
  const invoice = {
    lines: [{ qty: 10, unitPrice: 1000, discountPercent: 2.5, vatRate: 0 }], // tier discount
  };
  const r = invoiceTotals(invoice);
  assert.equal(r.ok, true);
  assert.equal(r.value.subtotal, 10000);
  // Base discount: 10000 * 0.025 = 250
  // Remaining: 10000 - 250 = 9750
  // Bulk discount: 9750 * 0.025 = 243.75 -> 244 (banker's rounding)
  // Total discount: 250 + 244 = 494
  assert.equal(r.value.discount, 494);
  assert.equal(r.value.total, 9506);
});

