import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, lineTotal, invoiceTotals, addLine, removeLine, issueInvoice, applyVoucher } from '../src/invoices.js';

test('createInvoice creates a valid invoice with one line', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.customerId, 'C-003');
  assert.equal(r.value.issueDate, '2026-10-07');
  assert.equal(r.value.status, 'draft');
  assert.equal(r.value.lines.length, 1);
  const line = r.value.lines[0];
  assert.equal(line.sku, 'DES-HOUR');
  assert.equal(line.name, 'Design work (hour)');
  assert.equal(line.qty, 5);
  assert.equal(line.unitPrice, 8500);
  assert.equal(line.vatRate, 21);
});

test('createInvoice normalizes customer ID (lowercase)', () => {
  const r = createInvoice({
    customerId: 'c-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.customerId, 'C-003');
});

test('createInvoice normalizes customer ID (with spaces)', () => {
  const r = createInvoice({
    customerId: ' c-003 ',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.customerId, 'C-003');
});

test('createInvoice defaults to NET30 terms', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.terms, 'NET30');
  // 30 days from 2026-10-07 = 2026-11-06
  assert.equal(r.value.dueDate, '2026-11-06');
});

test('createInvoice accepts NET14 terms', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'NET14',
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.terms, 'NET14');
  // 14 days from 2026-10-07 = 2026-10-21
  assert.equal(r.value.dueDate, '2026-10-21');
});

test('createInvoice accepts NET30 terms explicitly', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'NET30',
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.terms, 'NET30');
  assert.equal(r.value.dueDate, '2026-11-06');
});

test('createInvoice accepts EOM terms', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'EOM',
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.terms, 'EOM');
  // Last day of October
  assert.equal(r.value.dueDate, '2026-10-31');
});

test('createInvoice EOM with issue date on last day of month', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-31',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'EOM',
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.dueDate, '2026-10-31');
});

test('createInvoice EOM on February in non-leap year', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-02-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'EOM',
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.dueDate, '2026-02-28');
});

test('createInvoice EOM on February in leap year', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2024-02-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'EOM',
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.dueDate, '2024-02-29');
});

test('createInvoice EOM year boundary', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-12-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'EOM',
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.dueDate, '2026-12-31');
});

test('createInvoice rejects unknown terms', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'NET60',
  });
  assert.deepEqual(r, { ok: false, error: 'TERMS_INVALID' });
});

test('createInvoice NET14 spans month boundary', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-25',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'NET14',
  });
  assert.equal(r.ok, true);
  // 14 days from 2026-10-25 = 2026-11-08
  assert.equal(r.value.dueDate, '2026-11-08');
});

test('applyVoucher applies voucher to draft invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 0 }],
  });
  assert.equal(invoice.ok, true);

  const r = applyVoucher(invoice.value, { code: 'WELCOME10', amount: 5000 });
  assert.equal(r.ok, true);
  assert.equal(r.value.voucher.code, 'WELCOME10');
  assert.equal(r.value.voucher.amount, 5000);
});

test('applyVoucher does not mutate the input invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 0 }],
  });
  const original = invoice.value;

  applyVoucher(original, { code: 'WELCOME10', amount: 5000 });

  assert.equal(original.voucher, undefined);
});

test('applyVoucher rejects non-integer amount', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 0 }],
  });
  assert.equal(invoice.ok, true);

  const r = applyVoucher(invoice.value, { code: 'WELCOME10', amount: 100.5 });
  assert.deepEqual(r, { ok: false, error: 'AMOUNT_INVALID' });
});

test('applyVoucher rejects zero amount', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 0 }],
  });
  assert.equal(invoice.ok, true);

  const r = applyVoucher(invoice.value, { code: 'WELCOME10', amount: 0 });
  assert.deepEqual(r, { ok: false, error: 'AMOUNT_INVALID' });
});

test('applyVoucher rejects negative amount', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 0 }],
  });
  assert.equal(invoice.ok, true);

  const r = applyVoucher(invoice.value, { code: 'WELCOME10', amount: -100 });
