test('addLine and removeLine preserve other fields', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'DES-HOUR', qty: 3 },
    ],
  });
  assert.equal(invoice.ok, true);

  const added = addLine(invoice.value, { sku: 'DES-HOUR', qty: 1 });
  assert.equal(added.ok, true);
  assert.equal(added.value.customerId, 'C-003');
  assert.equal(added.value.issueDate, '2026-10-07');
  assert.equal(added.value.status, 'draft');

  const removed = removeLine(added.value, 'DES-HOUR');
  assert.equal(removed.ok, true);
  assert.equal(removed.value.customerId, 'C-003');
  assert.equal(removed.value.issueDate, '2026-10-07');
  assert.equal(removed.value.status, 'draft');
});

