test('invoiceTotals calculates discount correctly', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 100, discountPercent: 10 }],
  });
  assert.equal(invoice.ok, true);
  const r = invoiceTotals(invoice.value);
  assert.equal(r.ok, true);
  // 100 * 8500 = 850000, 10% discount = 85000
  // Remaining: 765000, bulk discount 2.5% = 19125
  // Total discount: 85000 + 19125 = 104125
  // Amount after discounts: 745875, VAT 21% = 156633 (rounded)
  assert.equal(r.value.subtotal, 850000);
  assert.equal(r.value.discount, 104125);
  assert.equal(r.value.vat, 156633);
  assert.equal(r.value.total, 902508);
});

test('invoiceTotals sums discounts from multiple lines', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 10, discountPercent: 10 },
      { sku: 'DEV-HOUR', qty: 10, discountPercent: 20 },
    ],
  });
  assert.equal(invoice.ok, true);
  const r = invoiceTotals(invoice.value);
  assert.equal(r.ok, true);
  // Line 1: 10 * 8500 = 85000, 10% discount = 8500, after = 76500, VAT 21% = 16065
  // Line 2: 10 * 9500 = 95000, 20% discount = 19000, after = 76000, VAT 21% = 15960
  // Total discount: 27500, Total VAT: 32025
  assert.equal(r.value.subtotal, 180000);
  assert.equal(r.value.discount, 27500);
  assert.equal(r.value.vat, 32025);
  assert.equal(r.value.total, 180000 - 27500 + 32025);
});

