  // 14 days from 2026-10-25 = 2026-11-08
  assert.equal(r.value.dueDate, '2026-11-08');
});

test('applyVoucher applies voucher to draft invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 0 }],
  });
  assert.equal(invoice.ok, true);

  const r = applyVoucher(invoice.value, { code: 'WELCOME10', amount: 5000 });
  assert.equal(r.ok, true);
  assert.equal(r.value.voucher.code, 'WELCOME10');
  assert.equal(r.value.voucher.amount, 5000);
});

test('applyVoucher does not mutate the input invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 0 }],
  });
  const original = invoice.value;

  applyVoucher(original, { code: 'WELCOME10', amount: 5000 });

  assert.equal(original.voucher, undefined);
});

test('applyVoucher rejects non-integer amount', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 0 }],
  });
  assert.equal(invoice.ok, true);

  const r = applyVoucher(invoice.value, { code: 'WELCOME10', amount: 100.5 });
  assert.deepEqual(r, { ok: false, error: 'AMOUNT_INVALID' });
});

test('applyVoucher rejects zero amount', () => {
  const invoice = createInvoice({
