      { qty: 1, unitPrice: 100, discountPercent: 150 },
    ],
  };
  const r = invoiceTotals(invoice);
  assert.equal(r.ok, true);
  assert.equal(r.value.subtotal, 100);
  assert.equal(r.value.discount, 150);
  assert.equal(r.value.total, 0);
});

test('invoiceTotals handles decimal discounts with rounding', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 4, discountPercent: 12.5 }],
  });
  assert.equal(invoice.ok, true);
  const r = invoiceTotals(invoice.value);
  assert.equal(r.ok, true);
  // 4 * 8500 = 34000, 12.5% discount = 4250
  // After discount: 29750, VAT 21% = 6247.50 -> 6248
  assert.equal(r.value.subtotal, 34000);
  assert.equal(r.value.discount, 4250);
  assert.equal(r.value.vat, 6248);
  assert.equal(r.value.total, 34000 - 4250 + 6248);
});

test('addLine accepts discountPercent', () => {
