  // C-001 should have gold tier = 5% discount
  assert.equal(r.value.lines[0].discountPercent, 5);
});

test('createInvoice applies standard tier discount', () => {
  const r = createInvoice({
    customerId: 'C-004',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(r.ok, true);
  // C-004 should have standard tier = 0% discount
  assert.equal(r.value.lines[0].discountPercent, 0);
